class Solution {
public:
    int minimumKeypresses(string s) {
        vector<int> freq(26);
        for (char c : s) ++freq[c - 'a'];
        sort(freq.rbegin(), freq.rend());
        int answer = 0;
        for (int i = 0; i < 26; ++i) answer += freq[i] * (i / 9 + 1);
        return answer;
    }
};
